describe('Profile Picture Upload', () => {
    beforeEach(() => {
        cy.visit('/user/profile');
    });

    it('should upload a profile picture and display the preview', () => {
        const fileName = 'profile-pic.jpg';
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('.preview-image').should('be.visible');
            cy.get('.preview-image').should('have.attr', 'src').and('include', fileName);
        });
    });

    it('should show an error message when uploading an invalid file type', () => {
        const invalidFileName = 'invalid-file.txt';
        cy.fixture(invalidFileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(invalidFileName);
            cy.get('.error-message').should('be.visible').and('contain', 'Invalid file type. Please upload a JPG or PNG image.');
        });
    });
});
